export interface WoolProps extends LayerProps {
  /** Strength of the relief shading applied to the child content Default: 0.5 */
  intensity?: number;
  /** Scale of the pattern — lower = larger features, higher = finer grain Default: 4 */
  scale?: number;
  /** Contrast of the texture — negative flattens it into a subtle overlay Default: -0.5 */
  contrast?: number;
  /** Surface distortion — warps the child along the texture like carved relief Default: 0.15 */
  distortion?: number;
  /** Random seed for pattern variation Default: 0 */
  seed?: number;
}

/** Applies an interwoven fibrous fabric texture and distortion to child content (Stylize; filters its children) */
export function Wool(props?: WoolProps, children?: ShaderNode[]): ShaderNode {
  return node('Wool', props, children);
}

export interface WorleyNoiseProps extends LayerProps {
  /** Color where the noise field is low (typically near cell centers) Default: "#ffffff" */
  colorA?: string;
  /** Color where the noise field is high (typically near cell boundaries) Default: "#000000" */
  colorB?: string;
  /** Color space for color interpolation Default: "linear" */
  colorSpace?: 'linear' | 'oklch' | 'oklab' | 'hsl' | 'hsv' | 'lch';
  /** Number of cells across the canvas at the base octave Default: 6 */
  scale?: number | PropDriver;
  /** Field type. F1 = distance to nearest point. F2 = distance to second-nearest. F2 − F1 emphasises cell boundaries. Default: "f1" */
  mode?: 'f1' | 'f2' | 'f2MinusF1' | 'f1PlusF2' | 'f1TimesF2';
  /** Distance metric. Euclidean = round cells. Manhattan = diamond. Chebyshev = square. Default: "euclidean" */
  distance?: 'euclidean' | 'manhattan' | 'chebyshev';
  /** Number of fractal layers stacked at progressively finer scales Default: 1 */
  octaves?: number;
  /** Scale multiplier between octaves (only active when Octaves > 1) Default: 2 */
  lacunarity?: number | PropDriver;
  /** Amplitude multiplier between octaves (only active when Octaves > 1) Default: 0.5 */
  persistence?: number | PropDriver;
  /** How much each cell's point drifts inside its cell. 0 = rigid grid (banded look), 1 = fully random. Default: 1 */
  jitter?: number | PropDriver;
  /** Steepness of the gradient between low and high regions Default: 1 */
  contrast?: number | PropDriver;
  /** Shifts the gradient midpoint. Negative pulls the field toward Color A, positive toward Color B. Default: 0 */
  balance?: number | PropDriver;
  /** Random seed — shifts the cell pattern without changing its overall structure Default: 0 */
  seed?: number | PropDriver;
  /** Animation speed — how fast each cell's point drifts Default: 0.5 */
  speed?: number;
}

/** Cellular noise field — distance-based, with selectable feature combinations and fractal octaves (Textures) */
export function WorleyNoise(props?: WorleyNoiseProps, children?: ShaderNode[]): ShaderNode {
  return node('WorleyNoise', props, children);
}

export interface ZoomBlurProps extends LayerProps {
  /** Intensity of the zoom blur effect Default: 30 */
  intensity?: number | PropDriver;
  /** Center point of the zoom blur Default: {"x":0.5,"y":0.5} */
  center?: Position | PropDriver;
  /** Spectral color fringing along the streak, like light through a lens; negative flips which end is red Default: 0 */
  dispersion?: number | PropDriver;
  /** Concentrates the dispersion away from the center; 0 fringes everywhere equally Default: 0 */
  falloff?: number | PropDriver;
  /** Radius of a clean zone around the center that stays sharp Default: 0 */
  focus?: number | PropDriver;
  /** Slides the streak window: 0 streaks inward from each pixel, 1 streaks evenly both ways, -1 pushes it further in Default: 0 */
  bias?: number | PropDriver;
  /** Lets bright pixels streak further than dark ones, like light rays Default: 0 */
  highlights?: number | PropDriver;
  /** Twists the radial streak into a vortex around the center Default: 0 */
  spiral?: number | PropDriver;
  /** Per-pixel noise on the tap spacing that hides banding in long streaks Default: 0 */
  jitter?: number | PropDriver;
}

/** Radial zoom blur expanding from a center point (Blurs; filters its children) */
export function ZoomBlur(props?: ZoomBlurProps, children?: ShaderNode[]): ShaderNode {
  return node('ZoomBlur', props, children);
}

